local LoafPanMaker = {}
local PRODUCTS = {
    iron_loafpan = { name = "Železni pekač za hlebce", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pekač za hlebce za pekove." },
    bronze_loafpan = { name = "Bronast pekač za hlebce", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pekač za hlebce za pekove." },
    silver_loafpan = { name = "Srebrn pekač za hlebce", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pekač za hlebce za pekove." },
    gilded_loafpan = { name = "Pozlačen pekač za hlebce", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pekač za hlebce za pekove." },
    jewel_set_loafpan = { name = "Draguljast pekač za hlebce", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pekač za hlebce za pekove." },
    royal_sovereign_loafpan = { name = "Kraljevski suveren pekač za hlebce", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pekač za hlebce z biseri za krono." },
}
local BUILDINGS = {
    loafpan_workshop = { name = "Loafpan delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    loafpan_house = { name = "Loafpan hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_loafpan_atelier = { name = "Mojstrski loafpan atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_loafpan_palace = { name = "Suverena loafpan palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
LoafPanMaker.ironStock=18; LoafPanMaker.bronzeStock=14; LoafPanMaker.woodStock=10; LoafPanMaker.leatherStock=8; LoafPanMaker.silverStock=8; LoafPanMaker.goldStock=6; LoafPanMaker.jewelStock=4; LoafPanMaker.pearlStock=4
LoafPanMaker.productStock = {}; LoafPanMaker.buildings = {}; LoafPanMaker.maker = nil; LoafPanMaker.activeMaking = {}; LoafPanMaker.totalProducts = 0; LoafPanMaker.dayTimer = 0
function LoafPanMaker.init() LoafPanMaker.ironStock=18; LoafPanMaker.bronzeStock=14; LoafPanMaker.woodStock=10; LoafPanMaker.leatherStock=8; LoafPanMaker.silverStock=8; LoafPanMaker.goldStock=6; LoafPanMaker.jewelStock=4; LoafPanMaker.pearlStock=4; LoafPanMaker.productStock={}; LoafPanMaker.buildings={}; LoafPanMaker.maker=nil; LoafPanMaker.activeMaking={}; LoafPanMaker.totalProducts=0; LoafPanMaker.dayTimer=0; print("[LoafPanMaker] Royal Loaf Pan Maker System initialized (6 products, 4 buildings)") end
function LoafPanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LoafPanMaker.maker={name=n or ("Pekačar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pekačar najet: %s (spretnost: %d)",LoafPanMaker.maker.name,s),"success") end; return true end
function LoafPanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LoafPanMaker.build(id) local ok,e=LoafPanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LoafPanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LoafPanMaker.getQualityBonus() local b=0; for _,bd in ipairs(LoafPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LoafPanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LoafPanMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LoafPanMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LoafPanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LoafPanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LoafPanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LoafPanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LoafPanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LoafPanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LoafPanMaker.buildings==0 then return false,"Potrebna pekačna delavnica" end; if not LoafPanMaker.maker then return false,"Potreben pekačar" end; return true end
function LoafPanMaker.make(pt,qty) qty=qty or 1; local ok,e=LoafPanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LoafPanMaker.ironStock=LoafPanMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LoafPanMaker.bronzeStock=LoafPanMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LoafPanMaker.woodStock=LoafPanMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LoafPanMaker.leatherStock=LoafPanMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LoafPanMaker.silverStock=LoafPanMaker.silverStock-d.silverCost*qty end; if d.goldCost then LoafPanMaker.goldStock=LoafPanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LoafPanMaker.jewelStock=LoafPanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LoafPanMaker.pearlStock=LoafPanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LoafPanMaker.maker then t=math.max(1,t-math.floor(LoafPanMaker.maker.skill/13)) end; table.insert(LoafPanMaker.activeMaking,{id="loafpan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LoafPanMaker.completeMaking(m) local q=1.0+(LoafPanMaker.getQualityBonus()/100); if LoafPanMaker.maker then q=q+(LoafPanMaker.maker.skill/140) end; q=math.min(2.5,q); LoafPanMaker.productStock[m.productType]=(LoafPanMaker.productStock[m.productType] or 0)+m.quantity; LoafPanMaker.totalProducts=LoafPanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LoafPanMaker.maker then LoafPanMaker.maker.itemsMade=LoafPanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LoafPanMaker.maker.skill=math.min(100,LoafPanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pekač izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"loafpan.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LoafPanMaker.update(dt) if not _G.state then return end; LoafPanMaker.dayTimer=LoafPanMaker.dayTimer+dt; if LoafPanMaker.dayTimer>=30 then LoafPanMaker.dayTimer=0; for i=#LoafPanMaker.activeMaking,1,-1 do local m=LoafPanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LoafPanMaker.completeMaking(m); table.remove(LoafPanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LoafPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LoafPanMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LoafPanMaker.getStats() return {ironStock=LoafPanMaker.ironStock,bronzeStock=LoafPanMaker.bronzeStock,woodStock=LoafPanMaker.woodStock,leatherStock=LoafPanMaker.leatherStock,silverStock=LoafPanMaker.silverStock,goldStock=LoafPanMaker.goldStock,jewelStock=LoafPanMaker.jewelStock,pearlStock=LoafPanMaker.pearlStock,productStock=LoafPanMaker.productStock,numBuildings=#LoafPanMaker.buildings,hasMaker=LoafPanMaker.maker~=nil,makerName=LoafPanMaker.maker and LoafPanMaker.maker.name or "—",makerSkill=LoafPanMaker.maker and LoafPanMaker.maker.skill or 0,activeMaking=#LoafPanMaker.activeMaking,totalProducts=LoafPanMaker.totalProducts} end
return LoafPanMaker
